import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceExpiryTest {

    // 2026-10-02 02:30 in Warsaw (CEST). The cutoff is 2026-09-02 in Warsaw dates.
    private final Clock clock = Clock.fixed(Instant.parse("2026-10-02T00:30:00Z"), ZoneOffset.UTC);

    @Test
    void cancelsOnlyPlacedOrdersOlderThanThirtyWarsawDays() {
        OrderRepository repository = new OrderRepository();
        OrderService service = new OrderService(repository, clock);

        // 31 Warsaw days before today: stale.
        Order stale = placed(repository, "2026-09-01T10:00:00Z");
        // 30 days before today: not more than 30 days ago.
        Order fresh = placed(repository, "2026-09-02T10:00:00Z");
        // UTC date is Sep 1, but the Warsaw date is Sep 2: not stale.
        Order warsawBoundary = placed(repository, "2026-09-01T23:30:00Z");
        // Old but confirmed: not PLACED, so not touched.
        Order confirmed = placed(repository, "2026-08-01T10:00:00Z");
        confirmed.changeStatus("CONFIRMED");

        assertEquals(1, service.expireStale());

        assertEquals("CANCELLED", stale.status());
        assertEquals("PLACED", fresh.status());
        assertEquals("PLACED", warsawBoundary.status());
        assertEquals("CONFIRMED", confirmed.status());
    }

    @Test
    void isIdempotent() {
        OrderRepository repository = new OrderRepository();
        OrderService service = new OrderService(repository, clock);
        placed(repository, "2026-08-01T10:00:00Z");

        assertEquals(1, service.expireStale());
        assertEquals(0, service.expireStale());
    }

    private static Order placed(OrderRepository repository, String placedAt) {
        Order order = new Order(placedAt, "c-1", Money.pln(1000), Instant.parse(placedAt));
        repository.save(order);
        return order;
    }
}
}
